lue);box-shadow:0 0 0 3px rgba(67,136,255,.1)}.twocol{display:grid;grid-template-columns:1fr 1fr;gap:12px}.check{display:flex;align-items:center;gap:8px;color:#aebdd3;font-size:10px;margin:8px 0 16px}.check input{accent-color:#4388ff}.error{font-size:10px;color:#ff9c9c;margin-top:6px}.form-actions{display:flex;justify-content:flex-end;gap:9px;margin-top:15px}.tablewrap{overflow-x:auto}table{width:100%;border-collapse:collapse;min-width:620px}th{text-align:left;padding:11px 10px;color:#71839f;font-size:9px;text-transform:uppercase;letter-spacing:.08em;border-bottom:1px solid var(--line)}td{padding:13px 10px;border-bottom:1px solid rgba(152,177,220,.09);font-size:11px;color:#c1cde0}tr:last-child td{border-bottom:0}.rule-target b{display:block;color:#edf3ff}.rule-target span{display:block;color:#8293ad;font-size:10px;margin-top:4px}.action{font-size:9px;padding:5px 7px;border-radius:6px;color:#9ebdff;background:rgba(74,138,255,.1)}.action.block{color:#ffabab;background:rgba(255,100,100,.09)}.action.allow{color:#8fe0b8;background:rgba(127,224,178,.08)}.enabled{color:#8fe0b8;font-size:10px}.disabled{color:#f3cd86;font-size:10px}.rowactions{display:flex;gap:7px}.tiny{padding:6px 8px;border:1px solid var(--line);border-radius:7px;background:transparent;color:#9fb4d5;font-size:10px;cursor:pointer}.tiny.danger{color:#ffaaaa}.inlineedit{display:none;background:rgba(255,255,255,.02)}.inlineedit.open{display:table-row}.empty{text-align:center;padding:35px 15px;color:#8c9cb5;font-size:11px;line-height:1.7}.empty b{display:block;color:#dce7fa;font:600 14px 'Space Grotesk',sans-serif;margin-bottom:7px}.footnote{text-align:center;color:#667895;font-size:10px;margin-top:18px}
